package com.application.requiemproject.data.repository

import com.application.requiemproject.domain.model.HelpArticle
import com.application.requiemproject.domain.repository.HelpRepository

class LocalHelpRepository : HelpRepository {
    override fun articles() = listOf(
        HelpArticle(1, "Как начать перевод?", "Начало", "Выберите языки, нажмите «Начать перевод» и разрешите захват экрана. Откройте нужное приложение и нажмите плавающую кнопку «Обновить». OCR выделит текст рамками. Нажмите на рамку: перевод появится в карточке с прокруткой и сохранится до следующего обновления. После прокрутки или перехода на другой экран снова нажмите «Обновить»."),
        HelpArticle(2, "OCR или Accessibility?", "Перевод", "OCR распознаёт текст на изображении. Accessibility читает доступный текст элементов интерфейса; для него нужно включить службу Requiem в специальных возможностях Android. В обоих режимах только текст выбранной вами рамки отправляется выбранному сервису перевода."),
        HelpArticle(3, "Почему нет перевода?", "Перевод", "Нажмите на рамку нужного текста: перевод начинается только после выбора. При ошибке нажмите «Повторить» в рамке. Проверьте интернет, разрешение поверх приложений и выбранные языки. Защищённые приложения могут запрещать захват. Для смены языков приостановите захват в уведомлении и возобновите его."),
        HelpArticle(4, "Где хранятся снимки экрана?", "Приватность", "Кадры обрабатываются в оперативной памяти и не сохраняются в галерею. Распознавание выполняется на устройстве. Только текст рамки, на которую вы нажали, передаётся выбранному сервису перевода."),
        HelpArticle(5, "Как остановить захват?", "Начало", "Откройте системную панель уведомлений и используйте действие остановки захвата. Чтобы начать заново, вернитесь в Requiem и подтвердите новую сессию."),
        HelpArticle(6, "Зачем указывать email?", "Приватность", "Email в профиле используется только в запросах к MyMemory. Его можно добавить или изменить в настройках профиля. Аккаунт Requiem хранится локально на этом устройстве."),
        HelpArticle(7, "Как выбрать переводчика?", "Перевод", "На экране перевода откройте «Кто переводит». MyMemory работает без API-ключа. Для ChatGPT / OpenAI, Gemini или Claude введите API-ключ выбранного сервиса и модель. Вариант «Другой сервис» поддерживает формат OpenAI Chat Completions: укажите ключ, модель и HTTPS-адрес API. Ключи сохраняются зашифрованными на устройстве. При смене сервиса во время захвата нажмите «Обновить».")
    )
}
